<?php
require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    if(isset($_POST['delete_passkey'])){$id=(int)$_POST['delete_passkey'];$s=$pdo->prepare('UPDATE webauthn_credentials SET revoked_at=NOW() WHERE id=? AND user_id=?');$s->execute([$id,user()['id']]);audit($pdo,'revoke_passkey','authentication',$id);flash('success','Device access removed.');redirect('profile.php');}
    $name=trim($_POST['name']);$phone=trim($_POST['phone']);
    if($_POST['password']??''){
        if(strlen($_POST['password'])<10)flash('error','Password must be at least 10 characters.');
        elseif($_POST['password']!==$_POST['confirm_password'])flash('error','Password confirmation does not match.');
        else{$pdo->prepare('UPDATE users SET name=?,phone=?,password_hash=?,force_password_change=0 WHERE id=?')->execute([$name,$phone,password_hash($_POST['password'],PASSWORD_DEFAULT),user()['id']]);flash('success','Profile and recovery password updated securely.');}
    }else{$pdo->prepare('UPDATE users SET name=?,phone=? WHERE id=?')->execute([$name,$phone,user()['id']]);flash('success','Profile updated.');}
    $_SESSION['user']['name']=$name;$_SESSION['user']['phone']=$phone;audit($pdo,'update','profile',user()['id']);redirect('profile.php');
}
$q=$pdo->prepare('SELECT id,device_name,last_used_at,created_at FROM webauthn_credentials WHERE user_id=? AND revoked_at IS NULL ORDER BY id DESC');$q->execute([user()['id']]);$passkeys=$q->fetchAll();
$setup=($_GET['setup']??'')==='biometric';
render_header('Profile','profile');page_title('My Profile','ACCOUNT & DEVICE SECURITY','Manage your profile, recovery access and fingerprint / Face ID devices.');
?><div class="grid layout-2"><article class="card"><div style="text-align:center;padding:15px"><span class="brand-mark" style="width:78px;height:78px;border-radius:25px;font-size:28px;margin:auto"><?=e(strtoupper(substr(user()['name'],0,1)))?></span><h2 style="margin-top:18px"><?=e(user()['name'])?></h2><p style="color:var(--muted)"><?=e(user()['role_name'])?></p><span class="status">SECURE SESSION</span></div><div class="branch-lines"><div class="branch-line"><span>Email</span><b><?=e(user()['email'])?></b></div><div class="branch-line"><span>Last login</span><b><?=user()['last_login_at']?date('d M Y H:i',strtotime(user()['last_login_at'])):'First login'?></b></div></div></article>
<article class="card passkey-card" data-passkey-setup="<?=$setup?'auto':'manual'?>" data-csrf="<?=e(csrf_token())?>"><div class="passkey-head"><span class="passkey-icon"><i data-icon="fingerprint"></i></span><div><span class="eyebrow">PASSWORDLESS ACCESS</span><h2>Fingerprint / Face ID</h2><p>Unlock the app using this device—no email or password each time.</p></div></div><div class="form-alert biometric-message" data-passkey-message hidden></div><button class="btn primary" type="button" data-passkey-register><i data-icon="plus"></i>Add this device</button>
<div class="device-list"><?php foreach($passkeys as $key):?><div class="device-row"><span class="device-symbol"><i data-icon="shield"></i></span><div><b><?=e($key['device_name'])?></b><small>Added <?=date('d M Y',strtotime($key['created_at']))?><?= $key['last_used_at']?' · Last used '.date('d M H:i',strtotime($key['last_used_at'])):''?></small></div><form method="post"><?=csrf_field()?><button class="btn small danger" data-confirm="Remove biometric access for this device?" name="delete_passkey" value="<?=$key['id']?>">Remove</button></form></div><?php endforeach;?><?php if(!$passkeys):?><div class="empty compact"><div class="empty-icon"><i data-icon="fingerprint"></i></div>No biometric device has been added yet.</div><?php endif;?></div></article>
<article class="card"><div class="card-head"><div><h2>Profile details</h2><small>Password is kept only for emergency recovery and new-device setup.</small></div></div><form method="post" class="stack"><?=csrf_field()?><label>Full Name<input name="name" value="<?=e(user()['name'])?>" required></label><label>Phone<input name="phone" value="<?=e(user()['phone']??'')?>"></label><label>New Recovery Password<input type="password" name="password" minlength="10"></label><label>Confirm Recovery Password<input type="password" name="confirm_password"></label><button class="btn">Update Profile</button></form></article></div><?php render_footer('profile');
